const http=require("http"),fs=require("fs"),path=require("path");
const root=__dirname,port=Number(process.env.PORT||4188),types={".html":"text/html; charset=utf-8",".css":"text/css; charset=utf-8",".js":"text/javascript; charset=utf-8",".json":"application/json; charset=utf-8",".svg":"image/svg+xml"};
http.createServer((req,res)=>{let pathname=decodeURIComponent((req.url||"/").split("?")[0]);if(pathname==="/")pathname="/index.html";const file=path.resolve(root,"."+pathname);if(!file.startsWith(root+path.sep)&&file!==path.join(root,"index.html")){res.writeHead(403);return res.end("Forbidden");}fs.readFile(file,(err,data)=>{if(err){res.writeHead(err.code==="ENOENT"?404:500,{"Content-Type":"text/plain; charset=utf-8"});return res.end(err.code==="ENOENT"?"Not Found":"Server Error");}res.writeHead(200,{"Content-Type":types[path.extname(file)]||"application/octet-stream","Cache-Control":"no-store"});res.end(data);});}).listen(port,"127.0.0.1",()=>console.log("V8 prototype: http://127.0.0.1:"+port));
